CREATE OR REPLACE VIEW `images_products` AS select `pi`.`img_id` AS `img_id`,`i`.`path` AS `images`,`pi`.`created` AS `created`,`p`.`pro_id` AS `pro_id`,`p`.`company_id` AS `company_id`,NULL AS `imageBlob` from ((`products` `p` left join `product_images` `pi` on(`p`.`pro_id` = `pi`.`product_id` and `pi`.`deleted_at` is null)) left join `images` `i` on(`i`.`uuid` = `pi`.`image_id`)) order by `p`.`pro_id`;
